INSERT INTO public.stock_news VALUES
	(100, '000028', '国药一致：2026年一季度净利润2.87亿元', '中证智能财讯国药一致（000028）4月30日披露2026年第一季度报告。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605013727279598.html', '2026-05-01', '2026-06-05 20:21:36.368029+00'),
	(101, '000028', '国药一致：一季度归母净利润约2.87亿元 同比下降12.36%', '4月21日晚间，国药一致（000028.SZ）发布2026年一季度业绩快报。报告显示，其营业收入约178.23亿元，同比减少2.57%；归属于上市公司股东的净利润约2.87亿元，同比减少12.36%；基本每股收益0.52元，同比减少11.86%。（央广财经）', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604213712481288.html', '2026-04-21', '2026-06-05 20:21:36.368029+00'),
	(102, '000028', '社保基金连续持有54股 最长已持有60个季度', '002430 杭氧股份 28 2 5113.85 5.51 5.23 300783 三只松鼠 27 1 287.91 115.55 1.03 002847 盐津铺子 26 1 171.28 不变 0.70 300395 菲利华 26 2 1154.15 -22.16 2.26 000028', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604303726196858.html', '2026-04-30', '2026-06-05 20:21:36.368029+00'),
	(103, '000028', '国药一致Q1业绩快报：归母净利润同比降12.36%至2.87亿元', '4月21日，国药一致（000028）发布公告，2026年第一季度业绩快报显示，公司实现营业总收入约为178.23亿元，同比下降2.57%；归母净利润约为2.87亿元，同比下降12.36%。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604213712465673.html', '2026-04-21', '2026-06-05 20:21:36.368029+00'),
	(104, '000028', '国药一致：2026年一季度净利2.87亿元 同比下降12.36%', '中证智能财讯国药一致（000028）4月21日晚间披露2026年一季度业绩快报，公司实现营业收入178.23亿元，同比下降2.57%；归母净利润2.87亿元，同比下降12.36%；扣非净利润2.8亿元，同比下降11.77%；基本每股收益0.52元，加权平均净资产收益率为1.53%。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604213712738039.html', '2026-04-21', '2026-06-05 20:21:36.368029+00'),
