INSERT INTO public.stock_news VALUES
	(1624, '000090', '天健集团《公司章程》（2026年修订）', '', 'cninfo', 'announcement', 'https://www.cninfo.com.cn/new/disclosure/detail?annoId=1225351426', '2026-06-05', '2026-06-06 07:17:15.58905+00'),
	(1601, '000090', '天健集团(000090)龙虎榜数据(05-29)', '交易所2026年5月29日公布的交易公开信息显示，天健集团因成为连续三个交易日内，涨幅偏离值累计达到20%的证券上榜。天健集团当日收报3.85元，涨跌幅10.00%，换手率6.66%，成交额4.68亿。异常期间5月28日至5月29日，期间涨幅21.07%，累计偏离值22.10%，区间成交额', 'eastmoney', 'news', 'http://stock.eastmoney.com/a/202605293754463661.html', '2026-05-29', '2026-06-06 07:17:15.58905+00'),
	(1602, '000090', '天健集团：公司将进行重组整合的信息不实', '天健集团(000090)5月31日发布股票交易异常波动公告，公司近日关注到网络上流传关于本公司将进行重组整合的不实信息，引发关注，对此，公司澄清并郑重声明如下：截至目前，公司不存在正在筹划中的重大资产重组、股份发行、收购等重大事项。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605313755190485.html', '2026-05-31', '2026-06-06 07:17:15.58905+00'),
	(1603, '000090', '天健集团(000090.SZ)：2026年一季报净利润为-2331.45万元，同比由盈转亏', '2026年4月29日，天健集团(000090.SZ)发布2026年一季报。 　　公司营业总收入为36.90亿元，在已披露的同业公司中排名第4，较去年同报告期营业总收入增加8.05亿元，实现2年连续上涨，同比较去年同期上涨27.89%。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604293723698944.html', '2026-04-29', '2026-06-06 07:17:15.58905+00'),
	(1604, '000090', '租售同权概念下跌1.95%，主力资金净流出24股', '1.35 -13122.96 000002 万科A -3.24 2.18 -11363.38 600376 首开股份 -4.42 5.28 -4868.13 600895 张江高科 -0.75 1.62 -4168.82 600325 华发股份 -3.86 2.10 -2973.51 000090', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202606033759095171.html', '2026-06-03', '2026-06-06 07:17:15.58905+00'),
	(1605, '000090', '天健集团：董事长郑晓生因调动辞职', '天健集团（000090）发布公告，公司董事长郑晓生因工作调动原因，于2026年5月27日提交辞职报告，申请辞去公司董事、董事长及其他所有职务。 　　2026年一季度，天健集团实现收入36.90亿元，归母净利润-2331万元。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605273751421578.html', '2026-05-27', '2026-06-06 07:17:15.58905+00'),
