INSERT INTO public.stock_news VALUES
	(2300, '000410', '66股每笔成交量增长超50%', '10.02 51552 1125.68 000892 欢瑞世纪 -6.35 73022 815.75 603315 福鞍股份 -6.30 71770 740.59 300721 怡达股份 18.71 81769 568.48 300397 天和防务 8.70 86014 470.42 000410', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604243718566369.html', '2026-04-24', '2026-06-06 07:17:43.522329+00'),
	(2301, '000410', '直击CCMT2026：人形机器人赛道出圈 AI机床落地提速 高端增量订单锚定核心下游', '通用技术旗下沈阳机床（000410.SZ）集中亮相全系列自主可控高端智能装备，同步发布一体化人形机器人成套制造解决方案。其中VMU系列五轴加工中心，专为机器人大腿转接件、关节支架、异形结构件等复杂工件定制研发，适配多品种、高精度量产场景。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604263719180765.html', '2026-04-26', '2026-06-06 07:17:43.522329+00'),
	(2302, '000410', '沈阳机床：拟向关联方采购14台数控车床 涉金额2570万元', '南方财经4月9日电，沈阳机床（000410.SZ）公告，公司拟向关联方通用技术集团沈阳机床有限责任公司采购数控卧式车床14台，预计含税金额2570万元。2026年初至披露日，公司与该关联方累计发生日常采购4519.76万元，日常销售6054.71万元。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202604093699226594.html', '2026-04-09', '2026-06-06 07:17:43.522329+00'),
	(2303, '000410', '益民服务领先混合A：2025年换手率达3957.27%', 'AI基金益民服务领先混合A（000410）披露2025年年报，2025年基金利润604.91万元，加权平均基金份额本期利润0.3555元。报告期内，基金净值增长率为34.55%，截至2025年末，基金规模为2631.45万元。 　　该基金属于灵活配置型基金。', 'eastmoney', 'news', 'http://stock.eastmoney.com/a/202604113701995597.html', '2026-04-11', '2026-06-06 07:17:43.522329+00'),
