INSERT INTO public.stock_news VALUES
	(2394, '000417', '合百集团：公司通过基金间接投资长鑫科技的比例较低，间接投资金额较小', '合百集团（000417.SZ）5月22日在投资者互动平台表示，公司实缴出资1.8亿元参投了合肥市国联资本股权投资基金合伙企业（有限合伙），合肥市国联资本股权投资基金合伙企业（有限合伙）通过合肥产投壹号股权投资合伙企业（有限合伙）投资了长鑫科技集团股份有限公司，合肥市国联资本股权投资基金合伙企业', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605223746548248.html', '2026-05-22', '2026-06-06 07:17:43.522329+00'),
	(2395, '000417', '合百集团：截至目前，公司与长鑫科技无任何业务往来', '合百集团（000417.SZ）5月21日在投资者互动平台表示，截至目前，公司与长鑫科技无任何业务往来。目前公司没有根据相关规则应予披露而未披露的重要信息，公司严格按照监管规则履行信息披露义务，所有信息请以公司在指定信息披露媒体披露的公告为准，请理性投资，注意投资风险！', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605213745075051.html', '2026-05-21', '2026-06-06 07:17:43.522329+00'),
	(2396, '000417', '商贸零售行业资金流入榜：中国中免、步步高等净流入资金居前', '1.18 -1335.35 002072 凯瑞德 -6.21 7.16 -1386.27 002277 友阿股份 -4.84 4.10 -1881.29 601061 中信金属 -2.08 0.27 -1931.07 000759 中百集团 5.89 22.50 -2857.64 000417', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605293754559988.html', '2026-05-29', '2026-06-06 07:17:43.522329+00'),
	(2397, '000417', '合百集团：目前国联基金实缴资金总额约10.61亿元，其中公司实缴1.8亿元', '每经AI快讯，合百集团（000417.SZ）5月21日在投资者互动平台表示，2023年，为进一步拓宽公司产业投资布局，公司参投了合肥市国联资本股权投资基金合伙企业（有限合伙），公司作为有限合伙人（LP），以自有资金认缴出资9亿元。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605213745330160.html', '2026-05-21', '2026-06-06 07:17:43.522329+00'),
	(2398, '000417', 'A股午后拉升，三大股指收涨：算力硬件产业链延续强势', '商贸零售表现不佳，合百集团（000417）、东百集团（600693）等跌超8%，宁波中百（600857）、国芳集团（601086）、万辰集团（300972）、中百集团（000759）等跌超5%。', 'eastmoney', 'news', 'http://stock.eastmoney.com/a/202605283752724726.html', '2026-05-28', '2026-06-06 07:17:43.522329+00'),
	(2399, '000417', '8.26亿元资金今日流出商贸零售股', '-21125.87 601888 中国中免 -2.61 1.84 -18843.18 601933 永辉超市 -4.53 2.37 -13541.55 002251 步步高 -2.84 19.56 -8756.07 600693 东百集团 -9.04 8.27 -6912.49 000417', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605283752871667.html', '2026-05-28', '2026-06-06 07:17:43.522329+00'),
