INSERT INTO public.stock_news VALUES
	(3411, '000521', '长虹美菱已回购2258万股 金额1.5亿元', '长虹美菱（000521/200521）发布公告，截至2026年5月7日，公司已通过集中竞价交易回购2258万股A股股份，占总股本的2.19%，回购总金额为1.5亿元，回购价格区间为5.6元/股至7.45元/股。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605073730164391.html', '2026-05-07', '2026-06-07 16:00:02.122996+00'),
