INSERT INTO public.stock_news VALUES
	(8911, '000807', 'A股尾盘回暖，三大股指涨跌互现：有色金属领涨，算力硬件产业链下挫', '有色金属领涨，宇树机器人表现抢眼 　　在板块方面，有色金属领涨两市，盛龙股份（001257）、中国铝业（601600）、招金黄金（000506）、金钼股份（601958）等涨停，南山铝业（600219）、宏桥控股（002379）、云铝股份（000807）、天山铝业（002532）等涨超', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605263749604248.html', '2026-05-26', '2026-06-07 16:31:58.194283+00'),
	(8912, '000807', '云铝股份：公司电价按照市场化交易方式形成，并按规定结算', '云铝股份（000807.SZ）5月14日在投资者互动平台表示，公司电价按照市场化交易方式形成，并按规定结算。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605143737364837.html', '2026-05-14', '2026-06-07 16:31:58.194283+00'),
	(8913, '000807', '云铝股份：公司目前拥有80万吨阳极炭素产能', '云铝股份（000807.SZ）5月14日在投资者互动平台表示，公司目前拥有80万吨阳极炭素产能，全部用于保障内部电解铝生产需求。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605143737352960.html', '2026-05-14', '2026-06-07 16:31:58.194283+00'),
	(8914, '000807', '云铝股份：目前云南省电力供应情况稳定，公司处于满负荷生产状态', '云铝股份（000807.SZ）5月14日在投资者互动平台表示，目前云南省电力供应情况稳定，公司处于满负荷生产状态。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605143737364764.html', '2026-05-14', '2026-06-07 16:31:58.194283+00'),
	(8915, '000807', '云铝股份：目前公司以国内市场为主，铝产品大部分在国内销售，仅有少量铝产品出口', '近期如何 　　云铝股份（000807.SZ）5月14日在投资者互动平台表示，目前公司以国内市场为主，铝产品大部分在国内销售，仅有少量铝产品出口。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605143737364943.html', '2026-05-14', '2026-06-07 16:31:58.194283+00'),
	(8916, '000807', '云铝股份：目前公司在昆明阳宗海基地建成并投产了5万吨铝资源综合利用再生铝示范线', '云铝股份（000807.SZ）5月14日在投资者互动平台表示，目前公司在昆明阳宗海基地建成并投产了5万吨铝资源综合利用再生铝示范线。未来，公司将持续推动再生铝资源回收利用，进一步完善公司绿色铝材一体化产业链。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605143737364631.html', '2026-05-14', '2026-06-07 16:31:58.194283+00'),
	(8917, '000807', '云铝股份：光伏发电直流接入电解铝生产用电技术为行业首创，公司已在8个厂区建设分布式光伏项目', '云铝股份（000807.SZ）5月14日在投资者互动平台表示，光伏发电直流接入电解铝生产用电技术为行业首创，公司已在8个厂区建设分布式光伏项目，总装机容量252兆瓦。', 'eastmoney', 'news', 'http://finance.eastmoney.com/a/202605143737363925.html', '2026-05-14', '2026-06-07 16:31:58.194283+00'),
