INSERT INTO public.stock_news VALUES
	(10216, '000885', '上海段和段（郑州）律师事务所关于城发环境股份有限公司2025年度股东会的法律意见书', '', 'cninfo', 'announcement', 'https://www.cninfo.com.cn/new/disclosure/detail?annoId=1225286557', '2026-05-09', '2026-06-07 17:30:31.686694+00'),
